import sys, threading, http.server, json, urllib.error, importlib
sys.path.insert(0, '.')
import weather; importlib.reload(weather)
state = {'fail': 0, 'hits': 0}
class H(http.server.BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def do_GET(self):
        state['hits'] += 1
        if state['fail'] > 0:
            state['fail'] -= 1
            code = state.get('code', 503); self.send_response(code); self.end_headers(); return
        b = json.dumps({'temp': 20}).encode(); self.send_response(200); self.end_headers(); self.wfile.write(b)
srv = http.server.ThreadingHTTPServer(('127.0.0.1', 0), H)
threading.Thread(target=srv.serve_forever, daemon=True).start()
c = weather.WeatherClient(f'http://127.0.0.1:{srv.server_port}', backoff=0.01)
def run(fail, code=503):
    state.update(fail=fail, hits=0, code=code)
    try: r = c.get('x')
    except urllib.error.HTTPError as e: r = f'HTTPError {e.code}'
    return r, state['hits']
print(run(0), run(2), run(3), run(1, 500))
srv.shutdown()

